const $=(s,r=document)=>r.querySelector(s), $$=(s,r=document)=>[...r.querySelectorAll(s)];
const esc=s=>String(s??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]));
const money=(n,c='UGX')=>new Intl.NumberFormat('en-UG',{style:'currency',currency:c,maximumFractionDigits:c==='UGX'?0:2}).format(Number(n||0));
const date=x=>x?new Date(x).toLocaleDateString('en-GB',{day:'2-digit',month:'short',year:'numeric'}):'—';
const datetime=x=>x?new Date(x).toLocaleString('en-GB',{day:'2-digit',month:'short',year:'numeric',hour:'2-digit',minute:'2-digit'}):'—';
let data=null,view='dashboard';
let requestWizardStep=1;
const CONTROLLED_ROLES=['Program Approver','Finance Reviewer','Final Approver'];
const ROLE_ACCESS={
  Developer:['dashboard','new','requests','approvals','payments','history','suppliers','supplierapps','matrix','delegations','passports','audit','userroles'],
  Administration:['dashboard','new','requests','suppliers'],
  'Program Approver':['dashboard','new','requests','approvals','suppliers'],
  'Finance Reviewer':['dashboard','new','requests','approvals','suppliers','supplierapps'],
  'Final Approver':['dashboard','new','requests','approvals','suppliers'],
  Accounts:['dashboard','new','requests','payments','history','suppliers'],
  Auditor:['dashboard','new','requests','suppliers','supplierapps','audit'],
  'Supplier Verification Officer':['dashboard','new','requests','suppliers','supplierapps'],
  'Procurement Manager':['dashboard','new','requests','suppliers','supplierapps'],
  Supplier:['supplierhome','supplierapplication']
};
function canView(v){if(!data?.user)return false;let allowed=ROLE_ACCESS[data.user.role]||['dashboard','new','requests'];if(CONTROLLED_ROLES.includes(data.user.role)&&data.user.controlledRoleStatus!=='Active')allowed=['dashboard','new','requests','suppliers'];return allowed.includes(v)}
function avatarHtml(u,cls='avatar'){const pic=u?.profilePicture;return pic?`<div class="${cls} avatar-photo"><img src="${esc(pic)}" alt="${esc(u.name||'User')} profile picture"></div>`:`<div class="${cls}">${esc((u?.name||'U').split(/\s+/).map(x=>x[0]).slice(0,2).join('').toUpperCase())}</div>`}

async function api(url,opt={}){return window.ADRA_LOCAL_ENGINE.api(url,opt)}
function toast(msg){const t=$('#toast');t.textContent=msg;t.hidden=false;clearTimeout(window.__tt);window.__tt=setTimeout(()=>t.hidden=true,2800)}
function statusChip(s){let cls=/Fully Approved|Paid|Approved|Verified/.test(s)?'green':/Returned|Rejected|Conflict/.test(s)?'red':/Approval|Review|Submitted|Pending/.test(s)?'amber':'';return `<span class="chip ${cls}">${esc(s)}</span>`}
function supplierStatusChip(s){let cls=/Verified|Accepted/.test(s)?'green':/Rejected/.test(s)?'red':/Returned/.test(s)?'red':/Verification|Review|Submitted/.test(s)?'amber':'';return `<span class="chip ${cls}">${esc(s)}</span>`}
function supplierStageOwner(status){return status==='Under Verification'?'Supplier Verification Officer':status==='Finance Verification'?'Finance Reviewer':status==='Final Review'?'Procurement Manager / Head of Procurement':status==='Verified'?'Verified supplier':status==='Rejected'?'Closed':status==='Returned for Information'?'Supplier':'Supplier'}

function approverCommentClass(a){const stage=String(a?.stage||'').toLowerCase();const decision=String(a?.decision||'').toLowerCase();const approverStage=stage.includes('program/budget holder')||stage.includes('finance review')||stage.includes('final approval');if(!approverStage&&!['approved','verified','rejected','returned for correction'].includes(decision))return '';if(['approved','verified'].includes(decision))return 'approver-comment-approved';if(['rejected','returned for correction'].includes(decision))return 'approver-comment-alert';return 'approver-comment-alert'}
function isApproverComment(a){return !!approverCommentClass(a)}
function commentHtml(a){if(!a?.comments)return '<span class="muted">—</span>';const cls=approverCommentClass(a);return cls?`<span class="${cls}" title="Approver comment">${esc(a.comments)}</span>`:`<span>${esc(a.comments)}</span>`}
function approvalActorHtml(a){const u=data.users.find(x=>x.id===(a.signature?.signerId||a.actor))||{name:a.actorName||a.signature?.signerName||'Approver',profilePicture:''};return `<div class="approval-actor">${avatarHtml(u,'approval-face')}<div class="approval-actor-copy"><b>${esc(a.actorName||a.signature?.signerName||u.name)}</b><small>${esc(a.signature?.role||u.role||'')} ${a.signature?.staffCode?`• ${esc(a.signature.staffCode)}`:''}</small></div></div>`}

function getNotifications(){
  if(!data)return [];
  const rows=[];
  for(const t of data.transactions||[]){
    if(isMyApproval(t)) rows.push({kind:'approval',id:t.id,title:`Approval required: ${t.id}`,detail:`${t.type} • ${t.currentStage||t.status}${Number(t.amount)>0?` • ${money(t.amount,t.currency)}`:''}`});
    if(t.requester===data.user.id&&t.status==='Returned for Correction') rows.push({kind:'returned',id:t.id,title:`Returned for correction: ${t.id}`,detail:t.rejectionReturnReason||'Open the request, make the correction and resubmit.'});
    if(['Accounts','Developer'].includes(data.user.role)&&t.status==='Fully Approved'&&!t.paymentProcessed) rows.push({kind:'payment',id:t.id,title:`Ready for payment: ${t.id}`,detail:`${t.payee||t.type}${Number(t.amount)>0?` • ${money(t.amount,t.currency)}`:''}`});
  }
  return rows.slice(0,20);
}
function notificationCount(){return getNotifications().length}
function openNotifications(){
  const rows=getNotifications();
  modal(`<div class="modal-head"><div><h2 style="margin:0">Notifications</h2><div class="muted">Items that may need your attention.</div></div><button class="close" type="button" data-close>×</button></div><div class="modal-body">${rows.length?`<div class="notification-list">${rows.map(n=>`<button class="notification-item" type="button" data-notification-id="${esc(n.id)}" data-notification-kind="${esc(n.kind)}"><span class="notification-mark">${icon(n.kind==='payment'?'card':n.kind==='returned'?'alert':'inbox')}</span><span class="notification-copy"><b>${esc(n.title)}</b><small>${esc(n.detail)}</small></span>${icon('chevronRight','chevron-icon')}</button>`).join('')}</div>`:`<div class="notification-empty">No new workflow notifications for this user.</div>`}</div><div class="modal-foot"><button class="btn" type="button" data-close>Close</button></div>`);
  $$('[data-notification-id]',$('#modal')).forEach(b=>b.addEventListener('click',()=>{const id=b.dataset.notificationId;$('#modal').innerHTML='';openTx(id)}));
}
function currentPrincipal(t){if(t.status==='Program Approval')return t.programApprover;if(t.status==='Finance Review')return t.financeReviewer;if(t.status==='Final Approval'&&t.requiresSecondFinal&&t.firstFinalApproved)return t.secondFinalApprover;if(t.status==='Final Approval')return t.finalApprover;return null}
function isMyApproval(t){if(CONTROLLED_ROLES.includes(data.user.role)&&data.user.controlledRoleStatus!=='Active')return false;const p=currentPrincipal(t);if(!p)return false;if(p===data.user.id)return true;return data.delegations.some(d=>d.active&&d.principal===p&&d.delegate===data.user.id&&d.types.includes(t.type)&&new Date(d.start)<=new Date()&&new Date(d.end+'T23:59:59')>=new Date()&&(d.maxAmount==null||Number(t.amount)<=Number(d.maxAmount)))}
function user(id){if(data.user?.id===id)return data.user;return data.users.find(u=>u.id===id)||{name:id||'—',role:''}}
async function refresh(){data=await api('/api/bootstrap')}
function getNavScrollTop(){const nav=$('.nav');if(nav)return nav.scrollTop;const saved=Number(localStorage.getItem('adra_nav_scroll_top'));return Number.isFinite(saved)?saved:0}
function rememberNavScrollTop(){const nav=$('.nav');if(nav)localStorage.setItem('adra_nav_scroll_top',String(nav.scrollTop))}
function restoreNavScrollTop(pos){const nav=$('.nav');if(!nav)return;const value=Math.max(0,Number(pos)||0);nav.scrollTop=value;requestAnimationFrame(()=>{const current=$('.nav');if(current)current.scrollTop=value})}
function setView(v){if(!canView(v)){toast('This feature is not available for your role.');return}rememberNavScrollTop();view=v;render()}
