  let photoData='';$('#profilePicture')?.addEventListener('change',e=>{const f=e.target.files?.[0];if(!f)return;if(f.size>2*1024*1024){e.target.value='';toast('Profile picture must be 2 MB or smaller.');return}const rd=new FileReader();rd.onload=()=>{photoData=String(rd.result||'');$('#profilePreview').innerHTML=authAvatarPreview(photoData)};rd.readAsDataURL(f)});
