  $('#signupForm')?.addEventListener('submit',async e=>{e.preventDefault();const b=Object.fromEntries(new FormData(e.currentTarget));b.profilePicture=photoData;if(!photoData){toast('Please choose a profile picture.');return}try{const r=await api('/api/auth/signup',{method:'POST',body:JSON.stringify(b)});if(r.pendingVerification){toast('Account created. Your approval role is pending Developer verification. You may sign in and submit requests, but approval powers remain locked until verified.');showAuth('signin');return}await refresh();view=data.user.role==='Supplier'?'supplierhome':'dashboard';render();toast('Account created successfully')}catch(err){toast(err.message)}});
