async function loadSupplierDocs(){if(data.user.role!=='Supplier')return;try{const pack=await api('/api/supplier/application');const app=pack.application;const all=await api('/api/supplier/applications').catch(()=>null);let docs=[];if(all)docs=(all.attachments||[]).filter(x=>x.requestId===app.id);else{const raw=JSON.parse(localStorage.getItem('adraProcurementBrowserDB_v222')||'{}');docs=(raw.attachments||[]).filter(x=>x.requestId===app.id)}const host=$('#supplierDocs');if(host)host.innerHTML=docs.length?docs.map(x=>`<div class="doc-row"><span>${icon('requests')}</span><span><b>${esc(x.name)}</b><small>${datetime(x.uploadedAt)}</small></span></div>`).join(''):'<div class="muted">No supporting documents uploaded yet.</div>'}catch(e){const host=$('#supplierDocs');if(host)host.textContent='Unable to load documents.'}}
async function openSupplierApplication(id){const pack=window.__supplierPack||await api('/api/supplier/applications'),a=pack.applications.find(x=>x.id===id);if(!a)return toast('Supplier application not found');const d=a.data||{},checks=a.verificationChecks||{},criteria=pack.criteria||[],audit=(pack.supplierAudit||[]).filter(x=>x.applicationId===id);const canAct=data.user.role==='Developer'||(data.user.role==='Supplier Verification Officer'&&a.status==='Under Verification')||(data.user.role==='Finance Reviewer'&&a.status==='Finance Verification')||(data.user.role==='Procurement Manager'&&a.status==='Final Review');const stage=data.user.role==='Supplier Verification Officer'?'Procurement':data.user.role==='Finance Reviewer'?'Finance':'All';modal(`<div class="modal-head"><div><h2 style="margin:0">${esc(a.companyName)}</h2><div class="muted">${esc(a.id)} • ${esc(a.status)}</div></div><button class="close" data-close>×</button></div><div class="modal-body"><div class="supplier-review-grid"><div class="card card-pad"><h3>Supplier information</h3><dl class="details"><dt>Registration no.</dt><dd>${esc(d.registrationNumber||'—')}</dd><dt>TIN</dt><dd>${esc(d.taxId||'—')}</dd><dt>Address</dt><dd>${esc(d.physicalAddress||'—')}</dd><dt>Business type</dt><dd>${esc(d.businessType||'—')}</dd><dt>Services</dt><dd>${esc(d.goodsServices||'—')}</dd><dt>Owners / directors</dt><dd>${esc(d.directorsOwners||'—')}</dd><dt>Bank</dt><dd>${esc(d.bankName||'—')} • ${esc(d.bankAccountName||'—')} • ****${esc(String(d.bankAccountNumber||'').slice(-4))}</dd><dt>Conflict declaration</dt><dd>${esc(d.conflictDeclaration||'—')}</dd><dt>Anti-bribery</dt><dd>${esc(d.antiBriberyDeclaration||'—')}</dd><dt>Sanctions</dt><dd>${esc(d.sanctionsDeclaration||'—')}</dd></dl></div><div class="card card-pad"><h3>Verification score</h3><div class="big-score">${Number(a.score||0)}%</div><p class="muted">Minimum ${Number(data.settings.supplierMinimumScore||70)}%. Mandatory criteria must pass before final acceptance.</p></div></div><div class="criteria-list">${criteria.map(c=>`<label class="criteria-row ${c.mandatory?'mandatory':''}"><input type="checkbox" data-criterion="${c.id}" ${checks[c.id]===true?'checked':''} ${canAct&&(stage==='All'||c.stage===stage)?'':'disabled'}><span><b>${esc(c.label)}</b><small>${c.stage} verification • ${c.weight} points${c.mandatory?' • mandatory':''}</small></span><strong>${c.weight}</strong></label>`).join('')}</div><div class="field"><label>Reviewer comments</label><textarea id="supplierReviewComment" ${canAct?'':'disabled'}></textarea></div><div class="supplier-audit"><h3>Review history</h3>${audit.map(x=>`<div class="audit-mini"><b>${esc(x.decision)}</b><span>${esc(x.actorName)} • ${esc(x.role)} • ${datetime(x.at)}</span><small>${esc(x.comments||'')}</small></div>`).join('')||'<div class="muted">No review actions yet.</div>'}</div>${canAct?`<label class="confirm-check"><input type="checkbox" id="supplierSignConfirm"> I confirm this supplier verification action using my electronic identity.</label>`:''}</div><div class="modal-foot"><button class="btn" data-close>Close</button>${canAct?`<button class="btn danger" data-supplier-review-action="Reject">Reject</button><button class="btn" data-supplier-review-action="Return">Return for information</button>${a.status==='Final Review'?'<button class="btn good" data-supplier-review-action="Accept">Accept supplier</button>':'<button class="btn primary" data-supplier-review-action="Forward">Verify & forward</button>'}`:''}</div>`);$$('[data-supplier-review-action]',$('#modal')).forEach(b=>b.onclick=async()=>{if(!$('#supplierSignConfirm').checked)return toast('Confirm your electronic identity');const verificationChecks={};$$('[data-criterion]',$('#modal')).forEach(x=>verificationChecks[x.dataset.criterion]=x.checked);try{await api(`/api/supplier/applications/${id}/review`,{method:'POST',body:JSON.stringify({action:b.dataset.supplierReviewAction,comments:$('#supplierReviewComment').value,verificationChecks,signatureConfirmed:true})});await refresh();$('#modal').innerHTML='';render();toast('Supplier review decision recorded')}catch(e){toast(e.message)}})}
function wire(){const nav=$('.nav');if(nav)nav.addEventListener('scroll',()=>localStorage.setItem('adra_nav_scroll_top',String(nav.scrollTop)),{passive:true});$$('[data-nav-toggle]').forEach(b=>b.onclick=()=>{const id=b.dataset.navToggle,g=b.closest('.nav-group'),collapsed=!g.classList.contains('collapsed');g.classList.toggle('collapsed',collapsed);b.setAttribute('aria-expanded',String(!collapsed));b.title=`${collapsed?'Expand':'Collapse'} ${b.querySelector('span')?.textContent||''}`;const state=getCollapsedNav();state[id]=collapsed;localStorage.setItem('adra_nav_collapsed',JSON.stringify(state))});$$('[data-view]').forEach(b=>b.onclick=()=>setView(b.dataset.view));$$('[data-open]').forEach(b=>b.onclick=()=>openTx(b.dataset.open));$$('[data-pay]').forEach(b=>b.onclick=()=>payment(b.dataset.pay));$$('[data-bank]').forEach(b=>b.onclick=()=>bankChange(b.dataset.bank));$('#startRequest')?.addEventListener('click',()=>setView('new'));$('#newForm')?.addEventListener('submit',createRequest);if($('#newForm'))initRequestWizard();$('#supplierRef')?.addEventListener('change',e=>{const sp=data.suppliers.find(s=>s.id===e.target.value);if(sp){$('#payeeField').value=sp.name;$('#payeeField').dataset.fromSupplier='1'}else if($('#payeeField')?.dataset.fromSupplier==='1'){$('#payeeField').value='';delete $('#payeeField').dataset.fromSupplier}});$('#notificationsBtn')?.addEventListener('click',openNotifications);$('#roleBtn')?.addEventListener('click',openAccountMenu);$('#roleBtn2')?.addEventListener('click',openAccountMenu);$('#newSupplier')?.addEventListener('click',addSupplier);$$('[data-supplier-app]').forEach(b=>b.onclick=()=>openSupplierApplication(b.dataset.supplierApp));if($('#supplierApplicationForm')){loadSupplierDocs();$('#supplierApplicationForm').addEventListener('submit',async e=>{e.preventDefault();try{await api('/api/supplier/application',{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(e.currentTarget)))});await refresh();render();toast('Supplier application draft saved')}catch(err){toast(err.message)}});$('#uploadSupplierEvidence')?.addEventListener('click',async()=>{const f=$('#supplierEvidence')?.files?.[0];if(!f)return toast('Choose a document');try{await api('/api/supplier/application/attachments',{method:'POST',body:JSON.stringify({name:f.name,type:f.type,size:f.size,dataBase64:await fileToB64(f)})});toast('Supplier evidence uploaded');loadSupplierDocs()}catch(err){toast(err.message)}});$('#submitSupplierApplication')?.addEventListener('click',async()=>{try{const form=$('#supplierApplicationForm');await api('/api/supplier/application',{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(form)))});await api('/api/supplier/application/submit',{method:'POST',body:'{}'});await refresh();render();toast('Supplier application submitted for ADRA verification')}catch(err){toast(err.message)}})}$('#addMatrix')?.addEventListener('click',addMatrix);$('#addDelegation')?.addEventListener('click',addDelegation);$$('[data-passport]').forEach(b=>b.onclick=()=>openPassport(b.dataset.passport));$$('[data-verify-role]').forEach(b=>b.onclick=async()=>{try{await api(`/api/admin/users/${b.dataset.verifyRole}/verify-role`,{method:'POST'});await refresh();render();toast('Controlled approval role verified')}catch(e){toast(e.message)}});$$('[data-revoke-role]').forEach(b=>b.onclick=async()=>{if(!confirm('Revoke this controlled approval role? The user will still be able to submit requests but will lose approval powers.'))return;try{await api(`/api/admin/users/${b.dataset.revokeRole}/revoke-role`,{method:'POST'});await refresh();render();toast('Approval role revoked')}catch(e){toast(e.message)}});$$('[data-assign-role]').forEach(b=>b.onclick=()=>assignRoleDialog(b.dataset.assignRole));$$('[data-account-status]').forEach(b=>b.onclick=async()=>{const [id,status]=b.dataset.accountStatus.split('|');try{await api(`/api/admin/users/${id}/account-status`,{method:'POST',body:JSON.stringify({status})});await refresh();render();toast(`Account ${status.toLowerCase()}`)}catch(e){toast(e.message)}});const s=$('#search'),f=$('#statusFilter');if(s){const apply=()=>{const q=s.value.toLowerCase(),st=f.value;const rows=data.transactions.filter(t=>(!q||JSON.stringify(t).toLowerCase().includes(q))&&(!st||t.status===st));$('#requestTable').innerHTML=requestsTable(rows.slice().reverse());$$('[data-open]',$('#requestTable')).forEach(b=>b.onclick=()=>openTx(b.dataset.open));applyTablePagination($('#requestTable'),1)};s.oninput=apply;f.onchange=apply}}
